const b=$('Complete RSS Digest').first().json.body;
const pre=$('Verify Expected RSS Rows').first().json;
const e=$('Verify Per-Item Evidence Receipts').first().json;
const originals=$('Get Digest Processing Rows').all().map(x=>x.json).filter(r=>Number.isInteger(Number(r.id))&&r.status==='processing'&&r.digest_id===b.digest_id);
const updates=$input.all().map(x=>x.json).filter(r=>Number.isInteger(Number(r.id))&&r.status==='processed'&&r.digest_id===b.digest_id&&!!r.processed_at);
const originalIds=new Set(originals.map(r=>Number(r.id)));
const updatedIds=new Set(updates.map(r=>Number(r.id)));
const ok=pre.ok===true&&e.ok===true&&originals.length===pre.expected_count&&updates.length===pre.expected_count&&originalIds.size===pre.expected_count&&updatedIds.size===pre.expected_count&&[...originalIds].every(id=>updatedIds.has(id));
return [{json:{ok,stage:'after_update',digest_id:b.digest_id,expected_count:pre.expected_count,actual_count:updates.length,processed_count:updates.length}}];

function assessDigestEvidence(body,processing,receipts,pre) {
 const digest=String(body?.digest_id||"");
 const expected=Number(body?.item_count);
 const rows=processing.filter(r=>r&&typeof r==="object"&&Object.keys(r).length>0);
 const ev=receipts.filter(r=>r&&typeof r==="object"&&Object.keys(r).length>0);
 const fail=(reason,invalid=[])=>({ok:false,stage:"evidence_receipt",digest_id:digest,expected_count:expected,processing_count:rows.length,receipt_count:ev.length,reason,invalid_items:invalid.slice(0,5)});
 if(!pre||pre.ok!==true||pre.digest_id!==digest||pre.expected_count!==expected)return fail("precount_not_verified");
 if(!Number.isInteger(expected)||expected<1||rows.length!==expected)return fail("processing_count_mismatch");
 const byKey=new Map(),ids=new Set();
 for(const r of rows) {
   if(r.status!=="processing"||r.digest_id!==digest||typeof r.item_key!=="string"||!r.item_key.trim()||typeof r.url!=="string"||!r.url.trim()||!Number.isInteger(Number(r.id))||ids.has(Number(r.id))||byKey.has(r.item_key)) return fail("processing_identity_invalid",[String(r.item_key||r.id)]);
   ids.add(Number(r.id));byKey.set(r.item_key,r);
 }
 const byEvent=new Map();
 for(const e of ev){
   const key=String(e.event_id||"");
   if(!key||byEvent.has(key))return fail("duplicate_or_missing_receipt_id",[key]);
   byEvent.set(key,e);
 }
 const invalid=[];
 for(const [key,row] of byKey){
   const eventId=`rss.article.evidence_checked:${digest}:${key}`;
   const e=byEvent.get(eventId);
   if(!e){invalid.push({item_key:key,issue:"missing_receipt"});continue}
   if(e.category!=="rss.article.evidence_checked"||e.project!=="tech-intelligence"||e.status!=="completed"||e.correlation_id!==digest||e.url!==row.url||!Number.isFinite(Date.parse(String(e.occurred_at||"")))){invalid.push({item_key:key,issue:"event_lineage_invalid"});continue}
   let m;
   try{m=JSON.parse(String(e.metadata_object||""));}catch{invalid.push({item_key:key,issue:"invalid_metadata_json"});continue}
   if(!m||typeof m!=="object"||Array.isArray(m)||m.digest_id!==digest||m.item_key!==key||m.source_url!==row.url||!Number.isFinite(Date.parse(String(m.checked_at||"")))||!String(m.evidence_summary||"").trim()){
     invalid.push({item_key:key,issue:"receipt_fields_invalid"});continue
   }
   const d=m.disposition,s=m.source_read_status;
   if(d==="source_gap"){invalid.push({item_key:key,issue:"source_gap_unresolved"});continue}
   if(d==="verified"&&(s!=="verified"||!String(m.source_locator||"").trim())){invalid.push({item_key:key,issue:"verified_evidence_missing_locator"});continue}
   if(d==="excluded"&&(!["verified","partial","blocked","not_applicable"].includes(s)||!String(m.reason||"").trim())){invalid.push({item_key:key,issue:"excluded_missing_reason"});continue}
   if(!["verified","excluded"].includes(d)){invalid.push({item_key:key,issue:"invalid_disposition"});continue}
 }
 const allowed=new Set(Array.from(byKey.keys(),key=>`rss.article.evidence_checked:${digest}:${key}`));
 for(const key of byEvent.keys())if(!allowed.has(key))invalid.push({item_key:key,issue:"foreign_receipt"});
 if(invalid.length>0)return fail("incomplete_or_invalid_evidence",invalid);
 if(byEvent.size!==expected)return fail("receipt_count_mismatch");
 return {ok:true,stage:"evidence_receipt",digest_id:digest,expected_count:expected,processing_count:rows.length,receipt_count:ev.length,verified_count:ev.filter(e=>{try{return JSON.parse(String(e.metadata_object)).disposition==="verified"}catch{return false}}).length,excluded_count:ev.filter(e=>{try{return JSON.parse(String(e.metadata_object)).disposition==="excluded"}catch{return false}}).length};
}
const b=$('Complete RSS Digest').first().json.body;
const pre=$('Verify Expected RSS Rows').first().json;
const rows=$('Get Digest Processing Rows').all().map(x=>x.json);
const evidence=$input.all().map(x=>x.json);
return [{json:assessDigestEvidence(b,rows,evidence,pre)}];

